import java.util.*;

public class Main {
    boolean find132pattern(int[] nums) {
        Deque<Integer> stack = new ArrayDeque<>();                                    // a monotonic stack of "3" (nums[j]) candidates, decreasing left to right
        int third = Integer.MIN_VALUE;                                                  // the best (largest) "2" (nums[k]) value confirmed so far
        for (int i = nums.length - 1; i >= 0; i--) {                                    // walk RIGHT TO LEFT, treating each num as a candidate "1" (nums[i])
            if (nums[i] < third) return true;                                              // nums[i] < third < (something bigger, still on the stack): a full 132 pattern!
            while (!stack.isEmpty() && stack.peek() < nums[i]) {                            // nums[i] can "dominate" (become the "3" for) smaller stack entries
                third = stack.pop();                                                          // that dominated entry becomes the new best "2" candidate
            }
            stack.push(nums[i]);
        }
        return false;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        int[] nums1 = {3, 1, 4, 2};
        int[] nums2 = {1, 2, 3, 4};
        System.out.println(solution.find132pattern(nums1));
        System.out.println(solution.find132pattern(nums2));
    }
}

